import fs from "node:fs";
import path from "node:path";
import yaml from "js-yaml";
import { NextResponse } from "next/server";

const REPO_ROOT = path.resolve(process.cwd(), "..");
const DOCS_DIR = path.join(REPO_ROOT, "docs");
const PLANS_DIR = path.join(REPO_ROOT, "plans");
const TAXONOMY_PATH = path.join(DOCS_DIR, "taxonomy.yaml");

type DocMetadata = {
  path: string;
  title: string;
  updated: string;
  facets: {
    type: string;
    status: string;
    strategy?: {
      slug: string;
      version: string;
    };
    repo?: {
      path: string;
    };
  };
  tags: string[];
};

function parseFrontMatter(content: string): { frontmatter: any; body: string } {
  const frontMatterRegex = /^---\s*\n([\s\S]*?)\n---\s*\n([\s\S]*)$/;
  const match = content.match(frontMatterRegex);

  if (!match) {
    return { frontmatter: null, body: content };
  }

  try {
    const frontmatter = yaml.load(match[1]) as any;
    return { frontmatter, body: match[2] };
  } catch (err) {
    return { frontmatter: null, body: content };
  }
}

function extractTitle(content: string): string {
  const titleMatch = content.match(/^#\s+(.+)$/m);
  return titleMatch ? titleMatch[1].trim() : "Untitled";
}

function scanMarkdownFiles(dir: string, baseDir: string, relativeBase: string): DocMetadata[] {
  const docs: DocMetadata[] = [];

  if (!fs.existsSync(dir)) {
    return docs;
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(baseDir, fullPath);

    // Skip node_modules, .git, data directories
    if (entry.name.startsWith(".") || entry.name === "node_modules" || entry.name === "data") {
      continue;
    }

    if (entry.isDirectory()) {
      docs.push(...scanMarkdownFiles(fullPath, baseDir, relativeBase));
      continue;
    }

    if (!entry.name.endsWith(".md")) {
      continue;
    }

    try {
      const content = fs.readFileSync(fullPath, "utf-8");
      const { frontmatter, body } = parseFrontMatter(content);

      const doc: DocMetadata = {
        path: `${relativeBase}/${relativePath}`,
        title: frontmatter?.title || extractTitle(body),
        updated: frontmatter?.updated || new Date().toISOString().split("T")[0],
        facets: {
          type: frontmatter?.facets?.type || "note",
          status: frontmatter?.facets?.status || "active",
          ...(frontmatter?.facets?.strategy && { strategy: frontmatter.facets.strategy }),
          ...(frontmatter?.facets?.repo && { repo: frontmatter.facets.repo }),
        },
        tags: frontmatter?.tags || [],
      };

      docs.push(doc);
    } catch (err: any) {
      console.error(`Error reading ${fullPath}:`, err.message);
    }
  }

  return docs;
}

export async function GET() {
  try {
    // Load taxonomy
    let taxonomy: any = {};
    if (fs.existsSync(TAXONOMY_PATH)) {
      const taxonomyContent = fs.readFileSync(TAXONOMY_PATH, "utf-8");
      taxonomy = yaml.load(taxonomyContent) as any;
    }

    // Scan markdown files
    const docs: DocMetadata[] = [
      ...scanMarkdownFiles(DOCS_DIR, REPO_ROOT, "docs"),
      ...scanMarkdownFiles(PLANS_DIR, REPO_ROOT, "plans"),
    ];

    return NextResponse.json({
      taxonomy,
      docs,
      count: docs.length,
    });
  } catch (err: any) {
    return NextResponse.json(
      { error: err?.message ?? "Failed to generate docs manifest" },
      { status: 500 }
    );
  }
}

import fs from "node:fs";
import path from "node:path";
import { NextRequest, NextResponse } from "next/server";

const REPO_ROOT = path.resolve(process.cwd(), "..");

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const filePath = searchParams.get("path");

  if (!filePath) {
    return NextResponse.json({ error: "path parameter required" }, { status: 400 });
  }

  // Security: ensure path is within docs/ or plans/
  const normalizedPath = path.normalize(filePath);
  if (!normalizedPath.startsWith("docs/") && !normalizedPath.startsWith("plans/")) {
    return NextResponse.json({ error: "Invalid path" }, { status: 400 });
  }

  // Prevent directory traversal
  if (normalizedPath.includes("..")) {
    return NextResponse.json({ error: "Invalid path" }, { status: 400 });
  }

  const fullPath = path.join(REPO_ROOT, normalizedPath);

  if (!fs.existsSync(fullPath)) {
    return NextResponse.json({ error: "File not found" }, { status: 404 });
  }

  try {
    const content = fs.readFileSync(fullPath, "utf-8");
    return NextResponse.json({ content, path: normalizedPath });
  } catch (err: any) {
    return NextResponse.json(
      { error: err?.message ?? "Failed to read file" },
      { status: 500 }
    );
  }
}

"use client";

import { useEffect, useState } from "react";

type Taxonomy = {
  facets?: {
    type?: string[];
    status?: string[];
  };
  tags?: Record<string, any>;
};

type DocMetadata = {
  path: string;
  title: string;
  updated: string;
  facets: {
    type: string;
    status: string;
    strategy?: {
      slug: string;
      version: string;
    };
    repo?: {
      path: string;
    };
  };
  tags: string[];
};

type Manifest = {
  taxonomy: Taxonomy;
  docs: DocMetadata[];
  count: number;
};

export default function DocsPage() {
  const [manifest, setManifest] = useState<Manifest | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedType, setSelectedType] = useState<string>("all");
  const [selectedStatus, setSelectedStatus] = useState<string>("all");
  const [selectedTag, setSelectedTag] = useState<string>("all");
  const [selectedDoc, setSelectedDoc] = useState<DocMetadata | null>(null);
  const [docContent, setDocContent] = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/docs/manifest")
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          setError(data.error);
        } else {
          setManifest(data);
        }
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    if (!selectedDoc) {
      setDocContent(null);
      return;
    }

    fetch(`/api/docs/content?path=${encodeURIComponent(selectedDoc.path)}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          setError(data.error);
        } else {
          setDocContent(data.content);
        }
      })
      .catch((err) => {
        setError(err.message);
      });
  }, [selectedDoc]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-950 text-slate-100">
        <div>Loading docs...</div>
      </div>
    );
  }

  if (error || !manifest) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-950 text-slate-100">
        <div className="text-red-400">Error: {error || "Failed to load docs"}</div>
      </div>
    );
  }

  const filteredDocs = manifest.docs.filter((doc) => {
    if (selectedType !== "all" && doc.facets.type !== selectedType) return false;
    if (selectedStatus !== "all" && doc.facets.status !== selectedStatus) return false;
    if (selectedTag !== "all" && !doc.tags.includes(selectedTag)) return false;
    return true;
  });

  const allTags = new Set<string>();
  manifest.docs.forEach((doc) => {
    doc.tags.forEach((tag) => allTags.add(tag));
  });
  const sortedTags = Array.from(allTags).sort();

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100">
      <div className="container mx-auto px-4 py-8">
        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2">Documentation Explorer</h1>
          <p className="text-slate-400">
            {filteredDocs.length} of {manifest.count} documents
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Filters Sidebar */}
          <div className="lg:col-span-1 space-y-4">
            <div className="bg-slate-900 rounded-lg p-4">
              <h2 className="font-semibold mb-3">Facets</h2>

              <div className="mb-4">
                <label className="block text-sm text-slate-400 mb-1">Type</label>
                <select
                  value={selectedType}
                  onChange={(e) => setSelectedType(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm"
                >
                  <option value="all">All Types</option>
                  {manifest.taxonomy.facets?.type?.map((type) => (
                    <option key={type} value={type}>
                      {type}
                    </option>
                  ))}
                </select>
              </div>

              <div className="mb-4">
                <label className="block text-sm text-slate-400 mb-1">Status</label>
                <select
                  value={selectedStatus}
                  onChange={(e) => setSelectedStatus(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm"
                >
                  <option value="all">All Statuses</option>
                  {manifest.taxonomy.facets?.status?.map((status) => (
                    <option key={status} value={status}>
                      {status}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm text-slate-400 mb-1">Tag</label>
                <select
                  value={selectedTag}
                  onChange={(e) => setSelectedTag(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm"
                >
                  <option value="all">All Tags</option>
                  {sortedTags.map((tag) => (
                    <option key={tag} value={tag}>
                      {tag}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Docs List */}
          <div className="lg:col-span-1">
            <div className="bg-slate-900 rounded-lg p-4 max-h-[600px] overflow-y-auto">
              <h2 className="font-semibold mb-3">Documents</h2>
              <div className="space-y-2">
                {filteredDocs.map((doc) => (
                  <button
                    key={doc.path}
                    onClick={() => setSelectedDoc(doc)}
                    className={`w-full text-left p-2 rounded text-sm hover:bg-slate-800 ${
                      selectedDoc?.path === doc.path ? "bg-slate-800 border border-slate-600" : ""
                    }`}
                  >
                    <div className="font-medium truncate">{doc.title}</div>
                    <div className="text-xs text-slate-400 mt-1">
                      {doc.facets.type} • {doc.facets.status}
                    </div>
                    {doc.facets.strategy && (
                      <div className="text-xs text-slate-500 mt-1">
                        {doc.facets.strategy.slug} v{doc.facets.strategy.version}
                      </div>
                    )}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Content Viewer */}
          <div className="lg:col-span-2">
            <div className="bg-slate-900 rounded-lg p-6">
              {selectedDoc ? (
                <div>
                  <div className="mb-4">
                    <h2 className="text-2xl font-bold mb-2">{selectedDoc.title}</h2>
                    <div className="text-sm text-slate-400 space-x-4">
                      <span>Updated: {selectedDoc.updated}</span>
                      <span>Path: {selectedDoc.path}</span>
                    </div>
                    {selectedDoc.tags.length > 0 && (
                      <div className="mt-2 flex flex-wrap gap-2">
                        {selectedDoc.tags.map((tag) => (
                          <span
                            key={tag}
                            className="px-2 py-1 bg-slate-800 rounded text-xs text-slate-300"
                          >
                            {tag}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                  {docContent ? (
                    <div className="prose prose-invert max-w-none">
                      <pre className="whitespace-pre-wrap text-sm bg-slate-800 p-4 rounded overflow-x-auto">
                        {docContent}
                      </pre>
                    </div>
                  ) : (
                    <div className="text-slate-400">Loading content...</div>
                  )}
                </div>
              ) : (
                <div className="text-slate-400 text-center py-12">
                  Select a document to view its content
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

