"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";

type DocMetadata = {
  path: string;
  title: string;
  updated: string;
  description?: string;
  facets: {
    type: string;
    status: string;
    strategy?: {
      slug: string;
      version: string;
    };
    repo?: {
      path: string;
    };
  };
  tags: string[];
};

export default function DocPage() {
  const params = useParams();
  const slug = params.slug as string[];
  const docPath = slug ? slug.join("/") : null;

  const [doc, setDoc] = useState<DocMetadata | null>(null);
  const [docContent, setDocContent] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!docPath) {
      setError("No document path provided");
      setLoading(false);
      return;
    }

    // First, get the manifest to find the doc metadata
    fetch("/api/docs/manifest")
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          setError(data.error);
          setLoading(false);
          return;
        }

        // Find the doc by path (handle both with and without .md extension)
        const foundDoc = data.docs.find(
          (d: DocMetadata) =>
            d.path === docPath ||
            d.path === `${docPath}.md` ||
            d.path.replace(/\.md$/, "") === docPath
        );

        if (!foundDoc) {
          setError("Document not found");
          setLoading(false);
          return;
        }

        setDoc(foundDoc);

        // Then fetch the content
        return fetch(`/api/docs/content?path=${encodeURIComponent(foundDoc.path)}`);
      })
      .then((res) => (res ? res.json() : null))
      .then((data) => {
        if (data?.error) {
          setError(data.error);
        } else if (data) {
          setDocContent(data.content);
        }
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  }, [docPath]);

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-950 text-slate-100">
        <header className="sticky top-0 z-20 border-b border-slate-800 bg-slate-950/90 backdrop-blur px-4 py-3">
          <div className="mx-auto flex max-w-6xl items-center justify-between gap-4">
            <div className="text-lg font-semibold text-white">Broz Backtester</div>
            <nav className="flex items-center gap-3 text-sm">
              <Link className="rounded-full px-3 py-1 text-slate-300 hover:bg-slate-800" href="/backtest">Backtest Tuner</Link>
              <Link className="rounded-full px-3 py-1 text-slate-300 hover:bg-slate-800" href="/analysis/dec2025-2yearbacktest-algo1.0">Backtest Analysis</Link>
              <Link className="rounded-full px-3 py-1 text-slate-300 hover:bg-slate-800" href="#">Downloader</Link>
              <Link className="rounded-full px-3 py-1 text-slate-300 hover:bg-slate-800" href="#">Trader</Link>
              <Link className="rounded-full bg-emerald-600 px-3 py-1 text-white" href="/docs">Docs</Link>
            </nav>
          </div>
        </header>
        <div className="flex items-center justify-center min-h-screen">
          <div>Loading document...</div>
        </div>
      </div>
    );
  }

  if (error || !doc) {
    return (
      <div className="min-h-screen bg-slate-950 text-slate-100">
