  const getInitialFilters = () => {
    const type = searchParams.get("type") || "all";
    const status = searchParams.get("status") || "all";
    const tags: Record<string, string> = {
      plan: searchParams.get("tag:plan") || "all",
      domain: searchParams.get("tag:domain") || "all",
      doc: searchParams.get("tag:doc") || "all",
      tech: searchParams.get("tag:tech") || "all",
      ops: searchParams.get("tag:ops") || "all",
      meta: searchParams.get("tag:meta") || "all",
      audience: searchParams.get("tag:audience") || "all",
    };
    return { type, status, tags };
  };

  const initialFilters = getInitialFilters();
  const [selectedType, setSelectedType] = useState<string>(initialFilters.type);
  const [selectedStatus, setSelectedStatus] = useState<string>(initialFilters.status);
  const [selectedTags, setSelectedTags] = useState<Record<string, string>>(initialFilters.tags);

