// Style code blocks
code: ({ node, inline, className, children, ...props }: any) => {
  // react-markdown passes inline as a boolean - true for inline, false/undefined for block
  // Block code has a className with language- prefix
  const isBlockCode = className && className.includes("language-");

  if (inline && !isBlockCode) {
    // Inline code - should not break lines unnecessarily
    return (
      <code className="bg-slate-800 px-1.5 py-0.5 rounded text-sm text-emerald-400 inline whitespace-nowrap" {...props}>
        {children}
      </code>
    );
  } else {
    // Block code - wrap in pre tag
    return (
      <pre className="bg-slate-800 p-4 rounded-lg overflow-x-auto text-sm my-4">
        <code className="text-emerald-400 block" {...props}>
          {children}
        </code>
      </pre>
    );
  }
},

