  // Check if this is a nested list (has a parent that's a list item)
  const depth = (node as any).depth || 0;
  const indentClass = depth > 0 ? `ml-${Math.min(depth * 4, 16)}` : '';
  return (
    <ul className={`list-disc mb-2 space-y-1 text-slate-300 ${indentClass}`} {...props}>
      {children}
    </ul>
  );
},
ol: ({ node, children, ...props }: any) => {
  const depth = (node as any).depth || 0;
  const indentClass = depth > 0 ? `ml-${Math.min(depth * 4, 16)}` : '';
  return (
    <ol className={`list-decimal mb-2 space-y-1 text-slate-300 ${indentClass}`} {...props}>
      {children}
    </ol>
  );
},
li: ({ node, children, ...props }: any) => {
  // Check if this list item contains nested lists
  const hasNestedList = node.children?.some((child: any) => child.type === 'list');
  return (
    <li className={`${hasNestedList ? 'mb-2' : ''} pl-2`} {...props}>
      {children}
    </li>
  );
},

