() => {
  const taskSection = Array.from(document.querySelectorAll('h2')).find(h => h.textContent?.includes('Tasks'));
  if (!taskSection) return { error: 'Tasks section not found' };

  let nextSibling = taskSection.nextSibling;
  while (nextSibling && nextSibling.nodeType !== 1) {
    nextSibling = nextSibling.nextSibling;
  }
  const tasksUl = nextSibling?.tagName === 'UL' ? nextSibling : nextSibling?.nextElementSibling;

  if (!tasksUl || tasksUl.tagName !== 'UL') return { error: 'Tasks list not found' };

  const firstTask = tasksUl.querySelector('li');
  if (!firstTask) return { error: 'No tasks found' };

  const nestedList = firstTask.querySelector('ul');
  const firstTaskText = firstTask.childNodes[0]?.textContent?.trim() || '';
  const firstNestedItem = nestedList?.querySelector('li');
  const firstNestedText = firstNestedItem?.textContent?.trim() || '';

  // Get the spacing between parent task text and nested list
  const parentTaskTextNode = Array.from(firstTask.childNodes).find(n => n.nodeType === 3 || (n.nodeType === 1 && n.tagName !== 'UL'));
  const nestedListElement = nestedList;

  if (parentTaskTextNode && nestedListElement) {
    const parentRect = parentTaskTextNode.nodeType === 1 ? parentTaskTextNode.getBoundingClientRect() : { bottom: 0 };
    const nestedRect = nestedListElement.getBoundingClientRect();
    const gap = nestedRect.top - (parentTaskTextNode.nodeType === 1 ? parentTaskTextNode.getBoundingClientRect().bottom : 0);

    return {
      firstTaskText: firstTaskText.substring(0, 50),
      firstNestedText: firstNestedText.substring(0, 40),
      hasNestedList: !!nestedList,
      gapBetweenParentAndNested: gap,
      parentTaskMarginBottom: window.getComputedStyle(firstTask).marginBottom,
      nestedListMarginTop: nestedList ? window.getComputedStyle(nestedList).marginTop : null
    };
  }

  return { error: 'Could not measure gap' };
}

