      .split(/\s+/)
      .filter(w => w.length > 2 && !['orb', 'r', 'v2'].includes(w.toLowerCase()));

    // Match H1 that might be similar to the title
    const h1Pattern = /^#\s+(.+)$/m;
    const h1Match = content.match(h1Pattern);
    if (h1Match) {
      const h1Text = h1Match[1].trim().toLowerCase();
      const h1KeyWords = h1Text
        .replace(/^(ticket[-:]?\s*\d*\s*)/i, '')
        .split(/\s+/)
        .filter(w => w.length > 2 && !['orb', 'r', 'v2'].includes(w.toLowerCase()));

      // Check if there's significant overlap in key words
