() => {
  // Find all section headings (h2) that have document links below them
  const allH2s = Array.from(document.querySelectorAll('h2'));
  const docSections = allH2s.filter(h2 => {
    // Check if this h2 is followed by document links
    let next = h2.nextElementSibling;
    while (next) {
      if (next.querySelector('a[href^="/docs/"]')) {
        return true;
      }
      next = next.nextElementSibling;
    }
    // Also check parent's next siblings
    const parent = h2.parentElement;
    if (parent) {
      let sibling = parent.nextElementSibling;
      while (sibling) {
        if (sibling.querySelector('a[href^="/docs/"]')) {
          return true;
        }
        sibling = sibling.nextElementSibling;
      }
    }
    return false;
  });

  const sectionInfo = docSections.map(h2 => {
    // Find the container with documents
    const container = h2.parentElement;
    const docLinks = container ? container.querySelectorAll('a[href^="/docs/"]') : [];
    return {
      heading: h2.textContent?.trim(),
      docCount: docLinks.length
    };
  });

  return {
    sectionHeadings: docSections.map(h => h.textContent?.trim()),
